    this.prefix = ''
  }

  function buildRoutePrefix (r, opts) {
    function _RoutePrefix () {}
    const R = new _RoutePrefix()
    R.prefix = r.prefix
    if (typeof opts.prefix === 'string') {
      R.prefix += opts.prefix
